import{_ as o,a,b as r,c as i,d as l,e as t,f as s,g as n,h as d,i as p,j as c,k as m,l as u,m as g,n as h,o as b,p as f}from"./chunks/M-S-SW-AW32.D9bypBBg.js";import{_ as v,o as w,c as _,a3 as x}from"./chunks/framework.g9mfNVRQ.js";const O=JSON.parse('{"title":"Installare su Wear OS","description":"","frontmatter":{"source_hash":"6617aa448f","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/smartwatch/wearinstall.md","filePath":"it/smartwatch/wearinstall.md"}'),S={name:"it/smartwatch/wearinstall.md"};function z(q,e,y,D,A,k){return w(),_("div",null,[...e[0]||(e[0]=[x('<p>Trovi la documentazione di riferimento <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">qui</a>.</p><div class="info custom-block"><p class="custom-block-title">Curiosità</p><p>Puoi usare alcuni di questi metodi anche con l&#39;app master Dexcom e con AAPS.</p></div><h3 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h3><p>L&#39;orologio deve essere compatibile con Android Wear OS e riportare il seguente logo:</p><img src="https://play-lh.googleusercontent.com/WmoV-m8b6x16sDRfzebu5b2vstcyBHRrpzCj6ODoh6hGuMa9Gg39EvnOk7z3qMa0_WM=s180-rw" style="zoom:50%;" align="left"><p>Gli orologi recenti si trovano <a href="https://wearos.google.com/" target="_blank" rel="noreferrer">qui</a>.<br> Tutti gli smartwatch Wear OS sono direttamente compatibili con xDrip, ma le <a href="https://www.androidpolice.com/2021/02/12/wear-os-is-making-app-sideloading-much-more-difficult/" target="_blank" rel="noreferrer">modifiche di Google</a> a Wear OS ne hanno reso più complessa l&#39;installazione.<br> I successivi cambiamenti di comportamento introdotti da Samsung e da Google con Wear OS 5 l&#39;hanno resa ancora più complicata.</p><h3 id="wear-os-versions" tabindex="-1">Versioni di Wear OS <a class="header-anchor" href="#wear-os-versions" aria-label="Permalink to &quot;Versioni di Wear OS {#wear-os-versions}&quot;">​</a></h3><p>Le vecchie versioni di Wear OS, come la 1.5 e la 1.6, sono ormai più complicate da usare con i telefoni moderni.<br> Wear OS 2 e 3 sono pienamente supportati.<br> Wear OS 4 e 5 possono presentare delle difficoltà.</p><h3 id="wear-os-1x" tabindex="-1">Wear OS 1.x <a class="header-anchor" href="#wear-os-1x" aria-label="Permalink to &quot;Wear OS 1.x {#wear-os-1x}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Android 15</p><p>Il vecchio pacchetto Android Wear 2.9 non è compatibile con Android 15.</p></div><p>Di solito si tratta del Sony Smartwatch 3 (<a href="https://www.sony.com/electronics/support/other-products-xperia-smart-devices/swr50" target="_blank" rel="noreferrer">SWR50</a>).</p><h4 id="method-1-easiest" tabindex="-1">Metodo 1 (il più semplice) <a class="header-anchor" href="#method-1-easiest" aria-label="Permalink to &quot;Metodo 1 (il più semplice) {#method-1-easiest}&quot;">​</a></h4><ol><li>Dissocia l&#39;orologio dal telefono se era già associato.</li><li>Disinstalla Wear OS dal telefono se è installato.<br> Se hai altri orologi Android Wear collegati, potresti doverli associare di nuovo.</li><li>Disattiva l&#39;aggiornamento automatico delle app di Google Play.</li><li>Installa <a href="https://www.apkmirror.com/apk/google-inc/android-wear/android-wear-2-9-0-185084575-gms-release/android-wear-smartwatch-2-9-0-185084575-gms-android-apk-download/" target="_blank" rel="noreferrer">Android Wear 2.9.0.185084575 GMS</a>.</li><li>Apri Android Wear e associa l&#39;orologio, accettando e consentendo tutto: se vuoi disattivare alcune funzioni, lo farai dopo aver completato l&#39;installazione di xDrip.</li><li>Al termine dell&#39;associazione, controlla che la versione di Google Play dell&#39;orologio sia <strong>superiore a 9</strong>.<br> Settings -&gt; About -&gt; Versions<br><img src="'+o+'" style="zoom:75%;"><br> Se non lo è: toccala 3 volte per forzare l&#39;aggiornamento e aspetta (anche alcune ore).<br><img src="'+a+'" style="zoom:75%;"></li><li>Seleziona un quadrante xDrip nell&#39;app Android Wear del telefono<br><img src="'+r+'" style="zoom:75%;"><br><img src="'+i+'" style="zoom:75%;"></li><li>Riattiva l&#39;aggiornamento automatico delle app di Google Play e aggiorna manualmente a <a href="https://play.google.com/store/apps/details?id=com.google.android.wearable.app" target="_blank" rel="noreferrer">Wear OS</a>.</li></ol><h4 id="method-2-with-a-computer" tabindex="-1">Metodo 2 (con un computer) <a class="header-anchor" href="#method-2-with-a-computer" aria-label="Permalink to &quot;Metodo 2 (con un computer) {#method-2-with-a-computer}&quot;">​</a></h4><ol><li>Installa <a href="https://play.google.com/store/apps/details?id=com.google.android.wearable.app" target="_blank" rel="noreferrer">Wear OS</a> e associa l&#39;orologio al telefono.</li><li>Controlla che la versione dei servizi Google Play dell&#39;orologio sia superiore a 9 (quella di fabbrica con il firmware più recente è la 8.7).<br> Settings -&gt; About -&gt; Versions<br><img src="'+o+'" style="zoom:75%;"><br><img src="'+a+'" style="zoom:75%;"><br> Se lo è, hai finito: vedi sopra come selezionare un quadrante xDrip.<br> Altrimenti continua qui sotto.</li><li><a href="https://www.apkmirror.com/apk/google-inc/google-play-services-android-wear/google-play-services-android-wear-9-8-41-release/google-play-services-9-8-41-534-130237018-android-apk-download/download/" target="_blank" rel="noreferrer">Scarica</a> una versione più recente dei servizi Google Play. Rinomina il file con un nome più corto, ad esempio <code>GPS.apk</code>.</li><li><a href="./../troubleshoot/ADB.html">Installa ADB e caricalo sull&#39;orologio</a>.</li></ol><h3 id="wear-os-2x-and-3x" tabindex="-1">Wear OS 2.x e 3.x <a class="header-anchor" href="#wear-os-2x-and-3x" aria-label="Permalink to &quot;Wear OS 2.x e 3.x {#wear-os-2x-and-3x}&quot;">​</a></h3><h4 id="method-1-easiest-1" tabindex="-1">Metodo 1 (il più semplice) <a class="header-anchor" href="#method-1-easiest-1" aria-label="Permalink to &quot;Metodo 1 (il più semplice) {#method-1-easiest-1}&quot;">​</a></h4><p>Non sempre è possibile completare questa procedura: se non riesce, prova il Metodo 2.</p><ol><li>Dissocia l&#39;orologio dal telefono se era già associato.</li><li>Disinstalla Wear OS dal telefono se è installato.<br> Se hai altri orologi Android Wear collegati, potresti doverli associare di nuovo.</li><li>Disattiva l&#39;aggiornamento automatico delle app di Google Play.</li><li>Installa una vecchia versione di Wear OS <a href="https://www.apkmirror.com/apk/google-inc/android-wear/android-wear-2-51-0-398446042-gms-release/wear-os-by-google-smartwatch-2-51-0-398446042-gms-android-apk-download/" target="_blank" rel="noreferrer">2.51.0.398446042.gms</a>.</li><li>Apri Android Wear e associa l&#39;orologio, accettando e consentendo tutto: se vuoi disattivare alcune funzioni, lo farai dopo aver completato l&#39;installazione di xDrip.</li><li>Sull&#39;orologio apri Settings, Apps &amp; Notifications, App Info, System Apps e cerca Google Play Store. Seleziona Remove Upgrades (disinstalla aggiornamenti). Conferma. (Nota: l&#39;orologio aggiornerà automaticamente l&#39;app, quindi una volta fatto il downgrade devi essere veloce.)<br><img src="'+l+'" style="zoom:65%;"></li><li>Sull&#39;orologio apri Google Play Store e scorri fino ad Apps on my Phone. Seleziona e installa xDrip.<br><img src="'+t+'" style="zoom:65%;"></li><li>Cambia il quadrante con uno di xDrip, con un tocco prolungato sul quadrante attuale.</li></ol><h4 id="method-2-best" tabindex="-1">Metodo 2 (il migliore) <a class="header-anchor" href="#method-2-best" aria-label="Permalink to &quot;Metodo 2 (il migliore) {#method-2-best}&quot;">​</a></h4><p><strong>Consigliato:</strong> segui <a href="https://www.youtube.com/watch?v=ejrmH-JEeE0" target="_blank" rel="noreferrer">questo video</a> che illustra la procedura nei dettagli.</p><p>Devi essere connesso al Wi-Fi, e così anche l&#39;orologio.</p><ol><li>Installa <a href="https://play.google.com/store/apps/details?id=com.google.android.wearable.app" target="_blank" rel="noreferrer">Wear OS</a> e associa l&#39;orologio.</li><li>Installa e apri <a href="https://play.google.com/apps/testing/org.freepoc.wearinstaller2" target="_blank" rel="noreferrer">Wear Installer 2</a> sul telefono.<br><img src="'+s+'" style="zoom:75%;"></li><li>Attiva la modalità sviluppatore sull&#39;orologio (istruzioni <a href="./../troubleshoot/ADB.html#smartwatch">qui</a>. Solo sull&#39;orologio, poi torna qui)</li><li>Attiva il debug ADB tramite Wi-Fi sull&#39;orologio.<br><img src="'+n+'" style="zoom:65%;"></li><li>Annota l&#39;indirizzo IP dell&#39;orologio.<br><img src="'+d+'" style="zoom:65%;"></li><li>Apri l&#39;app sull&#39;orologio e copia l&#39;indirizzo IP nell&#39;app sul telefono.<br> Tocca <code>Done</code><br><img src="'+p+'" style="zoom:75%;"></li><li>Seleziona xDrip<br><img src="'+c+'" style="zoom:75%;"><br> Wear Installer estrarrà l&#39;apk per lo smartwatch.<br><img src="'+m+'" style="zoom:75%;"><br> Se richiesto, accetta l&#39;autorizzazione al debug sull&#39;orologio.<br><img src="'+u+'" style="zoom:75%;"></li><li>Quando è pronto, seleziona <code>INSTALL</code> e lascia lavorare l&#39;app senza intervenire: possono servire alcuni minuti.<br><img src="'+g+'" style="zoom:75%;"></li><li>Osserva i messaggi durante la procedura, ma non intervenire.<br><img src="'+h+'" style="zoom:75%;"></li><li>Al termine, seleziona <code>FINISH</code>.<br><img src="'+b+'" style="zoom:75%;"></li><li>Se l&#39;installazione di xDrip sull&#39;orologio non è riuscita, riprova.</li></ol><h5 id="method-2-alternatives" tabindex="-1">Alternative al Metodo 2 <a class="header-anchor" href="#method-2-alternatives" aria-label="Permalink to &quot;Alternative al Metodo 2 {#method-2-alternatives}&quot;">​</a></h5><p>Usa <a href="https://play.google.com/store/apps/details?id=com.geminiman.wearosmanager" target="_blank" rel="noreferrer">GeminiMan Wear OS Manager</a> o <a href="https://play.google.com/store/apps/details?id=de.agondev.easyfiretools" target="_blank" rel="noreferrer">Easy Fire Tools</a> (procedura simile a quella sopra).</p><h4 id="method-3-with-a-computer" tabindex="-1">Metodo 3 (con un computer) <a class="header-anchor" href="#method-3-with-a-computer" aria-label="Permalink to &quot;Metodo 3 (con un computer) {#method-3-with-a-computer}&quot;">​</a></h4><ol><li>Installa <a href="./../troubleshoot/ADB.html">ADB</a>.</li><li>Scarica xDrip su un computer ed estrai l&#39;APK (è un file compresso).<br><strong>Deve essere esattamente la stessa versione che hai sul telefono.</strong></li><li>Apri il pacchetto APK di xDrip con un programma di archiviazione, ordina per dimensione i file sotto <code>res</code> e copia il più grande (è l&#39;apk wear incorporato, solo che non ha questo nome) nella cartella di ADB.</li><li>Carica l&#39;estensione Wear di xDrip sull&#39;orologio.</li></ol><h3 id="wear-os-5" tabindex="-1">Wear OS 5 <a class="header-anchor" href="#wear-os-5" aria-label="Permalink to &quot;Wear OS 5 {#wear-os-5}&quot;">​</a></h3><p>Google e Samsung hanno introdotto cambiamenti importanti in Wear OS 5 e non permettono facilmente i quadranti personalizzati.</p><p>L&#39;installazione dell&#39;app xDrip per l&#39;orologio va fatta con Wear Installer 2 seguendo <a href="https://www.youtube.com/watch?v=EvTGEnPA9PY" target="_blank" rel="noreferrer">questo video</a> (mostra il quadrante AAPS: la procedura è la stessa con l&#39;APK wear di xDrip).</p><p><strong>Se per errore cambi il quadrante con un altro, devi ripetere la procedura qui sopra.</strong></p><h3 id="update-xdrip-on-your-watch" tabindex="-1">Aggiornare xDrip sull&#39;orologio <a class="header-anchor" href="#update-xdrip-on-your-watch" aria-label="Permalink to &quot;Aggiornare xDrip sull&#39;orologio {#update-xdrip-on-your-watch}&quot;">​</a></h3><h4 id="wear-os-1x-1" tabindex="-1">Wear OS 1.x <a class="header-anchor" href="#wear-os-1x-1" aria-label="Permalink to &quot;Wear OS 1.x {#wear-os-1x-1}&quot;">​</a></h4><p>Per forzare l&#39;aggiornamento dell&#39;app dell&#39;orologio, basta sincronizzare tutte le app.<br><img src="'+f+'" style="zoom:75%;"></p><h4 id="wear-os-20-to-40" tabindex="-1">Wear OS da 2.0 a 4.0 <a class="header-anchor" href="#wear-os-20-to-40" aria-label="Permalink to &quot;Wear OS da 2.0 a 4.0 {#wear-os-20-to-40}&quot;">​</a></h4><p>Dovrai disinstallare e reinstallare l&#39;app wear ogni volta che <a href="./../use/update.html">aggiorni</a> xDrip sul telefono, per mantenere sincronizzate le due app.</p><p>A partire dal 13 aprile 2021, xDrip può aggiornare automaticamente la versione wear se hai già installato una versione compatibile (almeno la <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2021.04.13" target="_blank" rel="noreferrer">Nightly del 13 aprile 2021</a>).</p><p>Per la versione aggiornata, le <a href="https://github.com/NightscoutFoundation/xDrip/issues/1648" target="_blank" rel="noreferrer">istruzioni</a> sono le seguenti:</p><ul><li>Installa sull&#39;orologio l&#39;ultimo componente WearOS nightly di xDrip, ad esempio con l&#39;app Wear Installer, facendo il downgrade del Play Store o manualmente tramite adb (vedi sopra).</li><li>Assicurati che la modalità sviluppatore e il debug adb via Wi-Fi siano attivi sull&#39;orologio (vedi sopra: Wear OS 2 Metodo 2 passo 4)</li><li>Vai in xDrip Prefs sull&#39;orologio, scorri fino a <code>Force Update</code> e toccalo</li><li>Dovrebbe verificare ADB e chiedere l&#39;autorizzazione: seleziona <code>Always Allow</code></li><li>Probabilmente ti dirà che ADB non funziona perché serve l&#39;autorizzazione</li><li>Torna in xDrip Prefs sull&#39;orologio e tocca di nuovo Force Update</li><li>Questa volta dovrebbe dire che ADB è a posto e poi chiedere all&#39;app xDrip del telefono di inviare l&#39;ultima versione</li><li>La versione dovrebbe essere scaricata e xDrip si installerà da solo.</li></ul><p>Quando le versioni sono identiche non succederà granché, ma questa procedura può servire in futuro per forzare xDrip a inviare l&#39;ultima versione; in ogni caso dovrebbe anche rilevare automaticamente i cambi di versione e aggiornarsi in background. Per divertimento puoi installare l&#39;ultima nightly sull&#39;orologio, poi fare il downgrade sul telefono e verificare che la procedura di aggiornamento riporti l&#39;app dell&#39;orologio alla versione precedente. Le informazioni sulla versione dovrebbero comparire accanto alla scritta <code>Force Update</code>.</p><p>L&#39;idea è che non ti serva più Wear Installer o qualunque metodo tu abbia usato per la prima installazione (ad esempio adb da PC o il downgrade del Play Store), perché xDrip può aggiornarsi da solo.</p><h4 id="wear-os-50" tabindex="-1">Wear OS 5.0 <a class="header-anchor" href="#wear-os-50" aria-label="Permalink to &quot;Wear OS 5.0 {#wear-os-50}&quot;">​</a></h4><p>Reinstalla il quadrante con <a href="#wear-os-5">Wear Installer 2</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',45)])])}const I=v(S,[["render",z]]);export{O as __pageData,I as default};
